def is_undulating(n):
    """
    Check if a number is undulating, meaning the digits strictly increase and then decrease (like a wave).

    Args:
        n (int): The number to check.

    Returns:
        bool: True if the number is undulating, False otherwise.
    """
    s = str(n)
    if len(s) < 2:
        return False  # Single-digit numbers cannot be undulating

    # Check if the number alternates in a strictly increasing then decreasing pattern
    turn = 0  # 0: not started, 1: increasing, -1: decreasing
    for i in range(1, len(s)):
        if s[i] > s[i-1]:
            if turn == -1:
                return False
            turn = 1
        elif s[i] < s[i-1]:
            if turn == 1:
                turn = -1
            else:
                return False
        else:
            return False  # Equal adjacent digits are not allowed

    # Must have both increasing and decreasing sequences to be undulating
    return turn == -1 or (len(s) > 2 and turn == 0)
